//! How the panels show tool arguments that a panel struct edits (the
//! Foliage, Stone, Organic, Silhouette, Import, and edit sections): each
//! row is a property's label, hint (the tooltip), and slider or drag range,
//! merged into the schema property by [`super::schema::tools`] as
//! `schema::ui` and `schema::soft` would write it inline. `panels/props.rs`
//! draws `prop_label`, `prop_slider`, `prop_drag`, and `prop_check` from
//! it, so the panel names only the argument. `docs/op-properties.md` is the
//! design.

/// One argument as a panel shows it.
pub(super) struct PanelProp {
    pub tool: &'static str,
    pub key: &'static str,
    /// The panel label, the property's `title`.
    pub label: &'static str,
    /// The tooltip and short help.
    pub hint: &'static str,
    /// The slider or drag range.
    pub soft: Option<(f64, f64)>,
    /// Decimals a slider or drag shows.
    pub digits: Option<u64>,
    /// Drag speed per point.
    pub speed: Option<f64>,
}

